function conversationOrigin(c){
  const o=state.crm.opportunities.find(o=>o.conversation===c.id);
  const touch=selectedTouch({touches:state.crm.touches.filter(t=>t.opportunity===o?.id)});
  if(touch.source!=='paid')return '';
  const ad={...state.crm.ads.find(a=>a.ad_id===touch.ad_id),...touch.meta_snapshot};
  return `<div class="crm-origin"><strong>Campanha paga</strong><span>Campanha: ${esc(ad?.campaign_name||ad?.campaign_id||'Aguardando Meta')}</span><span>Conjunto: ${esc(ad?.adset_name||ad?.adset_id||'Aguardando Meta')}</span><span>Anúncio: ${esc(ad?.ad_name||touch.ad_id||'Não informado')}</span><span>Criativo: ${esc(ad?.creative?.name||ad?.creative?.id||'Aguardando Meta')}</span></div>`;
}
const icons={contacts:'♙',help:'?',metrics:'▥',crm:'▦',inbox:'▤',channels:'◈',users:'♙',settings:'⚙',activity:'◷',instagram:'◎',messenger:'ϟ',whatsapp:'◉'};
