function login(setup){sessionGeneration++;sessionIdentity='';observer.reset();notifications.clear();drafts.clear();replyComposer.clear();chatPositions.clear();unread.clear();app.innerHTML=`<div class="auth"><div class="auth-story"><a class="brand" aria-label="Espaço Acquarella"><img class="brand-image" src="/acquarella-logo.png" alt="Espaço Acquarella - Cuidado, beleza e bem-estar"></a><div><span class="eyebrow">CONVERSAS QUE CONECTAM</span><h1>Todos os canais.<br>Uma só conversa.</h1><p>Mais proximidade com seus clientes.<br>Mais clareza para sua equipe.</p><div class="auth-orbit"><span>◎</span><i>↔</i><span>◉</span><i>↔</i><span>ϟ</span></div></div><small>Central de comunicação · Acquarella</small></div><div class="auth-form"><div class="auth-box"><span class="eyebrow">SEU ESPAÇO DE ATENDIMENTO</span><h2>${setup?'Vamos começar?':'Bem-vindo de volta.'}</h2><p>${setup?'Crie a empresa e seu primeiro acesso de administrador.':'Entre para acompanhar suas conversas.'}</p><form id="auth">${setup?'<label>Empresa<input name="company" value="Acquarella" required></label><label>Seu nome<input name="name" placeholder="Como podemos chamar você?" required></label>':''}<label>E-mail<input name="email" type="email" autocomplete="username" placeholder="voce@empresa.com.br" required></label><label>Senha<input name="password" type="password" autocomplete="'+(setup?'new-password':'current-password')+'" minlength="12" placeholder="Pelo menos 12 caracteres" required></label><button class="primary full">${setup?'Criar minha central':'Entrar na central'} <span>→</span></button><p class="form-error" role="alert"></p></form><div class="auth-note">◈ ${setup?'Seus dados ficam separados por empresa.':'Acesso seguro e permissões por conta.'}</div></div></div></div>`;$('#auth').onsubmit=action(async e=>{e.preventDefault();const b=e.submitter||$('#auth .primary');b.disabled=true;const input=Object.fromEntries(new FormData(e.target));try{if(setup)await api('setup',input);await api('login',input);await refresh();}catch(err){$('.form-error').textContent=err.message;}finally{b.disabled=false;}},setup?'Criando central…':'Entrando…');}
