  list.scrollTop=top;if(focused)list.querySelector('[data-conversation="'+focused+'"]')?.focus({preventScroll:true});
  document.querySelectorAll('button[data-conversation]').forEach(b=>b.onclick=()=>{rememberChat();selected=b.dataset.conversation;const position=chatPositions.get(selected);mobileChat=true;$('.inbox').classList.add('mobile-chat');unread.delete(selected);notifications.read(selected);conversationList();const messages=$('.messages');if(messages)messages.scrollTop=position&&!position.bottom?position.top:messages.scrollHeight;$('#notification-count').textContent=notifications.count();});
